// spark.js: deck-themed building blocks for HyperFrames compositions.
// Reads window.THEME (theme.js, generated by `anim` from decks/themes/<name>).
//
// Coordinates: x and y are fractions of the usable frame (0..1). The usable frame is the
// whole canvas minus the camera room at the bottom (THEME.safeBottom, set by --camera).
// Sizes are px at 1080 on the short side; A.px() scales them to the real canvas, so the
// same scene renders portrait, square and landscape.
// Animate with transforms and opacity only (x, y, scale, opacity): `hyperframes lint`
// rejects left/top tweens because they stutter under frame capture.
(function () {
  const T = window.THEME;
  const W = T.W, H = T.H, UH = H - T.safeBottom;
  const s = Math.min(W, H) / 1080;
  const A = {
    T, W, H, UH, s,
    portrait: H > W, landscape: W > H,
    px: (v) => v * s,
    X: (f) => f * W,
    Y: (f) => f * UH,
    // offsets in px (at 1080 on the short side) as fractions, for spacing that holds in every format
    dx: (v) => (v * s) / W,
    dy: (v) => (v * s) / UH,
    tl: gsap.timeline({ paused: true }),
    root: null,
  };

  A.mount = function (id = "stage") {
    A.root = document.getElementById(id);
    Object.assign(A.root.style, { position: "absolute", inset: "0", background: "var(--a-bg)",
      color: "var(--a-fg)", fontFamily: "var(--a-sans)", overflow: "hidden" });
    return A;
  };

  // A positioned element, centred on (x, y) unless anchor says otherwise.
  A.el = function (html = "", { x = 0.5, y = 0.5, cls = "", css = {}, anchor = "center", parent } = {}) {
    const d = document.createElement("div");
    d.className = "a " + cls;
    d.innerHTML = html;
    Object.assign(d.style, { position: "absolute", left: A.X(x) + "px", top: A.Y(y) + "px" }, css);
    (parent || A.root).appendChild(d);
    const [xp, yp] = { center: [-50, -50], left: [0, -50], right: [-100, -50], top: [-50, 0], topleft: [0, 0] }[anchor];
    gsap.set(d, { xPercent: xp, yPercent: yp });
    return d;
  };

  A.text = (str, { size = 40, weight = 500, color = "var(--a-fg)", mono = false, maxw, align = "center", ...o } = {}) =>
    A.el(str, { ...o, css: { fontSize: A.px(size) + "px", fontWeight: weight, color, whiteSpace: maxw ? "normal" : "nowrap",
      width: maxw ? A.px(maxw) + "px" : "auto", textAlign: align, lineHeight: 1.2, letterSpacing: "-0.01em",
      fontFamily: mono ? "var(--a-mono)" : "var(--a-sans)", ...(o.css || {}) } });

  // Title block at the top of the usable frame.
  A.title = function (title, sub) {
    const t = A.text(title, { y: 0.075, size: A.portrait ? 84 : 72, weight: 700 });
    const u = sub ? A.text(sub, { y: 0.075 + A.dy(A.portrait ? 96 : 84), size: 34, weight: 400, color: "var(--a-mute)" }) : null;
    return [t, u];
  };

  // A box in one of the deck's diagram kinds: paper, accent, ink, ghost, soft, ok.
  A.box = function ({ x = 0.5, y = 0.5, w = 220, h = 120, kind = "paper", title = "", sub = "", radius = 14, size = 30 } = {}) {
    const k = T.box[kind] || T.box.paper;
    const inner = `<div style="font-weight:600;font-size:${A.px(size)}px;color:${k.title}">${title}</div>` +
      (sub ? `<div style="font-size:${A.px(size * 0.7)}px;color:${k.sub};margin-top:${A.px(6)}px">${sub}</div>` : "");
    return A.el(inner, { x, y, css: { width: A.px(w) + "px", height: A.px(h) + "px", background: k.fill === "none" ? "transparent" : k.fill,
      border: `${A.px(4)}px solid ${k.stroke}`, borderRadius: A.px(radius) + "px", display: "flex", flexDirection: "column",
      alignItems: "center", justifyContent: "center", textAlign: "center", boxSizing: "border-box" } });
  };

  A.dot = ({ x = 0.5, y = 0.5, r = 16, color = "var(--a-acc)", hidden = true } = {}) =>
    A.el("", { x, y, css: { width: A.px(2 * r) + "px", height: A.px(2 * r) + "px", borderRadius: "50%", background: color,
      opacity: hidden ? 0 : 1 } });

  // Horizontal or vertical rule between two points (fractions).
  A.line = function ({ x1, y1, x2, y2, color = "var(--a-mute)", width = 3 } = {}) {
    const dx = A.X(x2) - A.X(x1), dy = A.Y(y2) - A.Y(y1);
    const len = Math.hypot(dx, dy), ang = Math.atan2(dy, dx) * 180 / Math.PI;
    const d = A.el("", { x: x1, y: y1, anchor: "topleft", css: { width: len + "px", height: A.px(width) + "px",
      background: color, transformOrigin: "0 50%", marginTop: -A.px(width) / 2 + "px" } });
    gsap.set(d, { rotation: ang });
    return d;
  };

  // A code panel. Minimal highlighting: comments, strings, numbers, keywords.
  A.code = function (src, { x = 0.5, y = 0.5, w = 900, size = 28, label = "" } = {}) {
    const tk = T.tokens || {};
    const c = { com: tk["--ed-com"] || "#6C717A", str: tk["--ed-str"] || "#A9C98B", num: tk["--ed-num"] || "#E0A94A", key: T.acc };
    const esc = (t) => t.replace(/&/g, "&amp;").replace(/</g, "&lt;");
    const KW = /\b(def|class|return|import|from|as|with|for|in|if|else|lambda|SELECT|FROM|WHERE|GROUP|BY|AS|JOIN|ON|CREATE|VIEW|MEASURE|val|object|case)\b/g;
    const hl = src.split("\n").map((ln) => {
      const m = ln.match(/^(.*?)(#|--|\/\/)(.*)$/);
      let body = esc(m ? m[1] : ln);
      body = body.replace(/("[^"]*"|'[^']*')/g, `<span style="color:${c.str}">$1</span>`)
        .replace(/\b(\d+(\.\d+)?)\b/g, `<span style="color:${c.num}">$1</span>`)
        .replace(KW, `<span style="color:${c.key}">$1</span>`);
      return body + (m ? `<span style="color:${c.com}">${esc(m[2] + m[3])}</span>` : "");
    }).join("\n");
    const head = label ? `<div style="font-size:${A.px(size * 0.75)}px;color:${c.com};margin-bottom:${A.px(10)}px">${esc(label)}</div>` : "";
    return A.el(head + `<pre style="margin:0;font:inherit;white-space:pre">${hl}</pre>`, { x, y, css: {
      width: A.px(w) + "px", padding: `${A.px(26)}px ${A.px(30)}px`, boxSizing: "border-box", background: "var(--a-code-bg)",
      color: "var(--a-code-fg)", fontFamily: "var(--a-mono)", fontSize: A.px(size) + "px", lineHeight: 1.45,
      borderRadius: A.px(12) + "px", textAlign: "left" } });
  };

  // A table; hi = index of the row drawn in the accent.
  A.table = function (head, rows, { x = 0.5, y = 0.5, w = 900, size = 30, hi = -1 } = {}) {
    const cell = (v, i, th) => `<td style="padding:${A.px(12)}px ${A.px(18)}px;text-align:${i ? "right" : "left"};` +
      `${th ? "color:var(--a-mute);font-weight:500;" : ""}border-bottom:${A.px(2)}px solid var(--a-line)">${v}</td>`;
    const tr = (r, j, th) => `<tr style="${j === hi ? "color:var(--a-acc);font-weight:600" : ""}">${r.map((v, i) => cell(v, i, th)).join("")}</tr>`;
    return A.el(`<table style="border-collapse:collapse;width:100%;font-size:${A.px(size)}px">` +
      tr(head, -2, true) + rows.map((r, j) => tr(r, j, false)).join("") + "</table>", { x, y, css: { width: A.px(w) + "px" } });
  };

  // Small honest label at the bottom of the usable frame: "schematic timing, not measured",
  // or where the numbers come from.
  A.note = (str) => A.text(str, { y: 0.965, size: 26, weight: 400, color: "var(--a-mute)" });

  // Timeline helpers.
  A.in = (els, at, o = {}) => A.tl.fromTo([].concat(els).filter(Boolean), { opacity: 0, y: A.px(o.rise ?? 18) },
    { opacity: 1, y: 0, duration: o.dur ?? 0.5, ease: "power2.out", stagger: o.stagger ?? 0.08 }, at);
  A.out = (els, at, o = {}) => A.tl.to([].concat(els).filter(Boolean), { opacity: 0, duration: o.dur ?? 0.4, ease: "power1.in" }, at);

  // Register the timeline. Call last, with the composition's length in seconds.
  A.finish = function (seconds, id = "main") {
    A.tl.set({}, {}, seconds);
    window.__timelines = window.__timelines || {};
    window.__timelines[id] = A.tl;
    A.tl.seek(0);
  };

  window.A = A;
})();
